import dotenv from 'dotenv';
import fs from 'fs';
import path from 'path';

dotenv.config({ path: '.env.local' });

const apiKey = process.env.GOOGLE_GENAI_API_KEY;
if (!apiKey) {
  console.error("GOOGLE_GENAI_API_KEY is not set in .env.local!");
  process.exit(1);
}

const promptText = "A breathtaking, serene ocean landscape at sunset, cinematic lighting, warm golden hour, ultra high resolution, highly detailed photorealistic";

async function probe(model: string, method: string, body: any) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:${method}`;
  console.log(`Probing: POST ${url}`);
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': apiKey as string
      },
      body: JSON.stringify(body)
    });

    console.log(`Response status for ${model}:${method}: ${response.status}`);
    const text = await response.text();
    if (response.ok) {
      console.log(`SUCCESS on ${model}:${method}!`);
      const data = JSON.parse(text);
      return data;
    } else {
      console.log(`Error body:`, text.substring(0, 500));
    }
  } catch (err) {
    console.error(`Fetch error for ${model}:${method}:`, err);
  }
  return null;
}

async function run() {
  // Try shape 1: standard gemini-api format for imagen-3.0-generate-002
  let data = await probe('imagen-3.0-generate-002', 'generateImages', {
    prompt: { text: promptText },
    numberOfImages: 1,
    aspectRatio: "16:9",
    outputMimeType: "image/jpeg"
  });

  if (data) {
    saveImage(data);
    return;
  }

  // Try shape 2: flat prompt format for imagen-3.0-generate-002
  data = await probe('imagen-3.0-generate-002', 'generateImages', {
    prompt: promptText,
    numberOfImages: 1,
    aspectRatio: "16:9",
    outputMimeType: "image/jpeg"
  });

  if (data) {
    saveImage(data);
    return;
  }

  // Try shape 3: flat format for imagen
  data = await probe('imagen', 'generateImages', {
    prompt: promptText,
    numberOfImages: 1,
    aspectRatio: "16:9"
  });

  if (data) {
    saveImage(data);
    return;
  }

  // Try shape 4: generateImage
  data = await probe('imagen', 'generateImage', {
    prompt: promptText,
    numberOfImages: 1,
    aspectRatio: "16:9"
  });

  if (data) {
    saveImage(data);
    return;
  }
}

function saveImage(data: any) {
  console.log("Analyzing image response data keys:", Object.keys(data));
  const imgList = data.generatedImages || data.images || [];
  if (imgList.length === 0) {
    console.error("No images found in response!", JSON.stringify(data, null, 2));
    return;
  }

  const firstImg = imgList[0];
  console.log("Image object keys:", Object.keys(firstImg));

  let base64 = "";
  if (firstImg.image && firstImg.image.imageBytes) {
    base64 = firstImg.image.imageBytes;
  } else if (firstImg.bytesBase64Encoded) {
    base64 = firstImg.bytesBase64Encoded;
  } else if (firstImg.imageData) {
    base64 = firstImg.imageData;
  } else if (firstImg.data) {
    base64 = firstImg.data;
  }

  if (base64) {
    const dir = path.join(process.cwd(), 'public', 'molly-media');
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const filePath = path.join(dir, 'ocean_landscape.png');
    fs.writeFileSync(filePath, Buffer.from(base64, 'base64'));
    console.log(`IMAGE SAVED SUCCESSFULLY to ${filePath}`);
    console.log(`You can view it at: /molly-media/ocean_landscape.png`);
  } else {
    console.error("Could not find base64 image bytes in:", JSON.stringify(firstImg, null, 2));
  }
}

run().catch(console.error);
